CREW_TALK_2 = {
 1:[("Noor","Are you going to apply for the internship too?","هل ستتقدمين للتدريب أيضاً؟"),("Sara","Yes, and I'm going to ask about the scholarship in the same email.","نعم، وسأسأل عن المنحة في نفس الإيميل."),("Noor","Smart. What's your schedule like this week?","ذكي. كيف جدولك هذا الأسبوع؟"),("Sara","Packed, but I'll join the team meeting first.","مزدحم، لكنني سألتحق باجتماع الفريق أولاً.")],
 2:[("Hamad","Do you think it will rain during the match?","هل تظن أنها ستمطر أثناء المباراة؟"),("Ziad","Probably not. The forecast says it's unlikely.","على الأرجح لا. التوقعات تقول إنه غير مرجح."),("Hamad","I'm certain we'll win anyway.","أنا متأكد أننا سنفوز على أي حال."),("Ziad","Maybe. I believe in the team, definitely.","ربما. أؤمن بالفريق، بالتأكيد.")],
 3:[("Omar","Are you leaving for the concert straight after school?","هل ستغادرين للحفلة فور انتهاء المدرسة؟"),("Noor","Yes, and I'm meeting Sara at the ticket booth first.","نعم، وسأقابل سارة عند شباك التذاكر أولاً."),("Omar","Did you finish booking everything?","هل أنهيت حجز كل شيء؟"),("Noor","Almost. I just need to check the guest list.","تقريباً. أحتاج فقط لمراجعة قائمة الضيوف.")],
 4:[("Ziad","What happened while you were walking home?","ماذا حدث بينما كنت تمشي إلى المنزل؟"),("Hamad","It started raining suddenly, and as soon as I noticed, I ran.","بدأ المطر فجأة، وبمجرد أن لاحظت، ركضت."),("Ziad","Did anyone call you at that moment?","هل اتصل بك أحد في تلك اللحظة؟"),("Hamad","Yes, my mom, but by the time I answered, I was already soaked.","نعم، أمي، لكن بحلول وقت ردي، كنت مبللاً تماماً.")],
 5:[("Sara","Is attending the workshop mandatory or optional?","هل حضور الورشة إلزامي أم اختياري؟"),("Omar","Optional, but volunteering counts as extra responsibility.","اختياري، لكن التطوع يُحسب مسؤولية إضافية."),("Sara","Do we need permission from home for that?","هل نحتاج إذناً من المنزل لذلك؟"),("Omar","Yes, that part is definitely required.","نعم، هذا الجزء مطلوب بالتأكيد.")],
 6:[("Hamad","How did you finish so accurately and so quickly?","كيف أنهيت بدقة وبسرعة هكذا؟"),("Noor","I worked carefully, and I checked everything gently before submitting.","عملت بعناية، وتحققت من كل شيء برفق قبل التسليم."),("Hamad","I always rush and do it loudly and badly.","أنا دائماً أتسرع وأفعلها بصخب وبشكل سيئ."),("Noor","Try patiently next time, not quickly.","جرب بصبر المرة القادمة، وليس بسرعة.")],
 7:[("Ziad","Which phone is the most reliable, in your opinion?","أي هاتف الأكثر موثوقية، برأيك؟"),("Sara","The newer one is more expensive but healthier for the battery, honestly.","الأحدث أغلى لكنه أفضل للبطارية، بصراحة."),("Ziad","Is it really the most popular one at school?","هل هو حقاً الأكثر شعبية في المدرسة؟"),("Sara","Definitely. And it's cheaper than the one Omar has.","بالتأكيد. وهو أرخص من هاتف عمر.")],
 8:[("Omar","Are we still going on the road trip this weekend?","هل ما زلنا سنقوم برحلة برية هذا الأسبوع؟"),("Hamad","Yes, after I catch up on sleep and relax a little first.","نعم، بعد أن أعوض النوم وأسترخي قليلاً أولاً."),("Omar","Can we stop downtown for brunch on the way?","هل يمكننا التوقف في وسط المدينة لوجبة برانش في الطريق؟"),("Hamad","Definitely, and maybe a board game after.","بالتأكيد، وربما لعبة لوحية بعدها.")],
 9:[("Noor","Do you think technology will solve every future problem?","هل تظنين أن التكنولوجيا ستحل كل مشكلة مستقبلية؟"),("Sara","Not every problem, but I predict we'll discover a lot.","ليس كل مشكلة، لكنني أتوقع أننا سنكتشف الكثير."),("Noor","Will you succeed in your own goal, then?","هل ستنجحين في هدفك الخاص إذاً؟"),("Sara","I believe so. I'll achieve it step by step.","أعتقد ذلك. سأحققه خطوة بخطوة.")],
 10:[("Hamad","Are you allowed to skip chores this week?","هل مسموح لك بتخطي الأعمال المنزلية هذا الأسبوع؟"),("Ziad","No, but my parents trust me with the curfew now.","لا، لكن والداي يثقان بي في حظر التجول الآن."),("Hamad","Do they still need to give permission for outings?","هل ما زالا يحتاجان لإعطاء إذن للخروج؟"),("Ziad","Less than before. I'm more independent, and I respect that.","أقل من قبل. أنا أكثر استقلالية، وأحترم ذلك.")],
 11:[("Sara","Did you speak confidently in the interview?","هل تحدثت بثقة في المقابلة؟"),("Noor","I tried, and I kept good eye contact the whole time.","حاولت، وحافظت على تواصل بصري جيد طوال الوقت."),("Sara","Was your tone calm, or a little nervous?","هل كانت نبرتك هادئة، أم متوترة قليلاً؟"),("Noor","A little nervous, but I answered politely and honestly.","متوترة قليلاً، لكنني أجبت بأدب وصدق.")],
 12:[("Ziad","Which option is more affordable for you?","أي خيار أكثر بأسعار معقولة بالنسبة لك؟"),("Omar","The used one, and it seems durable enough.","المستعمل، ويبدو متيناً بما فيه الكفاية."),("Ziad","Is it worth it compared to the new one?","هل يستحق مقارنة بالجديد؟"),("Omar","I think so — it's efficient, and the price is reasonable.","أعتقد ذلك — إنه فعال، والسعر معقول.")],
 13:[("Noor","Were you scrolling your phone while I was talking?","هل كنت تتصفح هاتفك بينما كنت أتحدث؟"),("Hamad","Sorry, I was trying to focus, but the notifications were a distraction.","آسف، كنت أحاول التركيز، لكن الإشعارات كانت تشتيتاً."),("Noor","Set a timer next time so you stay productive.","اضبط مؤقتاً المرة القادمة لتبقى منتجاً."),("Hamad","Good idea. One task at a time from now on.","فكرة جيدة. مهمة واحدة في كل مرة من الآن.")],
 14:[("Sara","What's your biggest goal for next year?","ما أكبر هدفك للعام القادم؟"),("Ziad","To improve my grades and reach one big milestone.","تحسين درجاتي والوصول لإنجاز كبير واحد."),("Sara","Do you track your progress anywhere?","هل تتابع تقدمك في أي مكان؟"),("Ziad","In a diary. It keeps my motivation up.","في يوميات. هذا يبقي حماسي مرتفعاً.")],
 15:[("Omar","Did your point of view change after the debate?","هل تغيرت وجهة نظرك بعد المناظرة؟"),("Noor","A little — Hamad had a fair point and good evidence.","قليلاً — كان لحمد نقطة عادلة ودليل جيد."),("Omar","So you agree partly with the counterargument now?","إذاً أنت توافقين جزئياً على الحجة المضادة الآن؟"),("Noor","Partly. But my conclusion is still the same.","جزئياً. لكن استنتاجي ما زال كما هو.")],
 16:[("Hamad","Did you organize your notes before the rehearsal?","هل رتبت ملاحظاتك قبل البروفة؟"),("Sara","Yes, and I made a checklist with a backup plan too.","نعم، وأعددت قائمة تحقق مع خطة بديلة أيضاً."),("Hamad","Smart. Did you review the timeline?","ذكي. هل راجعت الجدول الزمني؟"),("Sara","Twice. Now I just need to rest before tomorrow.","مرتين. الآن أحتاج فقط للراحة قبل الغد.")],
 17:[("Ziad","Did you follow the instructions step by step?","هل اتبعت التعليمات خطوة بخطوة؟"),("Omar","Yes, and I double-checked everything before moving on.","نعم، وتحققت من كل شيء مرتين قبل المتابعة."),("Ziad","Was it smooth, or did something go wrong?","هل كان سلساً، أم حدث خطأ ما؟"),("Omar","Smooth. Doing it properly the first time saved time.","سلساً. فعلها بشكل صحيح من أول مرة وفّر الوقت.")],
 18:[("Noor","What tradition is the most colorful in your family?","أي تقليد هو الأكثر ألواناً في عائلتك؟"),("Sara","Our Eid customs, definitely. The food is part of our heritage too.","عادات العيد لدينا، بالتأكيد. الطعام جزء من تراثنا أيضاً."),("Noor","Is your lifestyle similar to your cousins' in other countries?","هل أسلوب حياتكم مشابه لأبناء عمكم في دول أخرى؟"),("Sara","Similar hospitality, different cuisine.","نفس الضيافة، مطبخ مختلف.")],
 19:[("Hamad","What was the most unexpected part of the school trip?","ما أكثر جزء غير متوقع في الرحلة المدرسية؟"),("Ziad","The headcount was wrong, and the chaperone had to recheck twice.","عدد الطلاب كان خاطئاً، واضطر المرافق لإعادة العد مرتين."),("Hamad","Was the itinerary still followed after that?","هل تم اتباع خطة الرحلة بعد ذلك؟"),("Ziad","Mostly. The lesson learned made it memorable anyway.","في الغالب. الدرس المستفاد جعلها لا تُنسى على أي حال.")],
}
